/* IDO 5.3 -O2 -mips2 donor for gl_func_000743C4 = libc lldiv (ldiv.c verbatim). */

typedef struct {
    long long quot;
    long long rem;
} lldiv_t;

lldiv_t lldiv(long long num, long long denom)
{
    lldiv_t ret;

    ret.quot = num / denom;
    ret.rem = num - denom * ret.quot;
    if (ret.quot < 0 && ret.rem > 0)
    {
        ret.quot++;
        ret.rem -= denom;
    }

    return ret;
}
